/*
 * A191113  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 3x-2 and 4x-2 are in a.
 * https://oeis.org/A191113
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is defined by the recurrence a(1) = 1; if x is in the set
 *            then 3x-2 and 4x-2 also belong to the set. The sequence is the
 *            sorted list of all distinct numbers generated by these rules.
 *            The code stores the sequence in a cache and generates further
 *            terms only when a larger index is requested
 * Range:     u8 n <= 16, u16 n <= 660, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>

/* ----- Dynamic array for the cache of sequence values ----- */
static seq_t *seq_cache = NULL;
static size_t cache_cap = 0;
static size_t cache_len = 0;

static void grow_cache(void) {
    size_t new_cap = cache_cap ? cache_cap * 2 : 64;
    seq_t *tmp = (seq_t *)realloc(seq_cache, new_cap * sizeof(seq_t));
    if (!tmp) abort();            /* out‑of‑memory */
    seq_cache = tmp;
    cache_cap = new_cap;
}

/* ----- Binary min‑heap for candidate numbers ----- */
static seq_t *heap = NULL;
static size_t heap_cap = 0;
static size_t heap_len = 0;

static void grow_heap(void) {
    size_t new_cap = heap_cap ? heap_cap * 2 : 64;
    seq_t *tmp = (seq_t *)realloc(heap, new_cap * sizeof(seq_t));
    if (!tmp) abort();
    heap = tmp;
    heap_cap = new_cap;
}

static void heap_push(seq_t val) {
    if (heap_len == heap_cap) grow_heap();
    heap[heap_len++] = val;
    /* sift‑up */
    size_t i = heap_len - 1;
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (heap[p] <= heap[i]) break;
        seq_t tmp = heap[p]; heap[p] = heap[i]; heap[i] = tmp;
        i = p;
    }
}

static seq_t heap_pop(void) {
    seq_t res = heap[0];
    heap[0] = heap[--heap_len];
    /* sift‑down */
    size_t i = 0;
    while (1) {
        size_t l = (i << 1) + 1;
        size_t r = l + 1;
        size_t smallest = i;
        if (l < heap_len && heap[l] < heap[smallest]) smallest = l;
        if (r < heap_len && heap[r] < heap[smallest]) smallest = r;
        if (smallest == i) break;
        seq_t tmp = heap[i]; heap[i] = heap[smallest]; heap[smallest] = tmp;
        i = smallest;
    }
    return res;
}

/* --------- Generate A191113 -------------------------------- */
seq_t a(idx_t n) {
    if (n == 0) return 0;          /* undefined for n=0, but safe */

    /* Fill the cache up to the requested index */
    while (cache_len < (size_t)n) {
        /* Seed the heap with the first term if needed */
        if (heap_len == 0) heap_push((seq_t)1);

        seq_t x = heap_pop();

        /* Skip duplicates: do not store or generate children again */
        if (cache_len > 0 && x == seq_cache[cache_len - 1])
            continue;

        /* Store the new distinct value */
        if (cache_len == cache_cap) grow_cache();
        seq_cache[cache_len++] = x;

        /* Generate the two new candidate numbers */
        seq_t y1 = 3 * x - 2;
        seq_t y2 = 4 * x - 2;
        heap_push(y1);
        heap_push(y2);
    }
    return seq_cache[n - 1];
}
